window.NOTES={"version":69,"chapters":[{"number":1,"title":"信息技术与计算机文化","summary":"计算机发展、信息表示、硬件、软件与计算机系统的基础概念。","sections":[{"id":"1.1","title":"信息与信息技术"},{"id":"1.2","title":"计算机技术概论"},{"id":"1.3","title":"计算机中信息的表示"},{"id":"1.4","title":"计算机系统"},{"id":"1.5","title":"微型计算机系统"}]},{"number":2,"title":"Windows 10 操作系统","summary":"操作系统特征、Windows界面、文件管理、系统设置与维护。","sections":[{"id":"2.1","title":"操作系统概述"},{"id":"2.2","title":"Windows 10 基础"},{"id":"2.3","title":"文件和文件夹管理"},{"id":"2.4","title":"控制面板"},{"id":"2.5","title":"Windows 10 的系统维护"},{"id":"2.6","title":"Windows 10 的实用工具"}]},{"number":3,"title":"字处理软件 Word 2016","summary":"文档编辑、格式排版、表格、图文混排与长文档功能。","sections":[{"id":"3.1","title":"使用 Office 2016 应用程序"},{"id":"3.2","title":"Word 2016 的基本操作"},{"id":"3.3","title":"文档格式化与排版"},{"id":"3.4","title":"表格制作"},{"id":"3.5","title":"图文混排"},{"id":"3.6","title":"文档的保护与打印"},{"id":"3.7","title":"Word 2016 的高级应用"}]},{"number":4,"title":"电子表格系统 Excel 2016","summary":"工作表操作、公式与函数、格式化、数据处理和图表。","sections":[{"id":"4.1","title":"Excel 2016 概述"},{"id":"4.2","title":"Excel 2016 的基本操作"},{"id":"4.3","title":"Excel 公式与函数"},{"id":"4.4","title":"格式化工作表"},{"id":"4.5","title":"数据处理"},{"id":"4.6","title":"使用图表"}]},{"number":5,"title":"演示文稿软件 PowerPoint 2016","summary":"幻灯片组织、外观、动画、切换与放映设置。","sections":[{"id":"5.1","title":"PowerPoint 2016 基础"},{"id":"5.2","title":"幻灯片页面设计"},{"id":"5.3","title":"幻灯片页面外观的修饰"},{"id":"5.4","title":"动画效果和动作设置"},{"id":"5.5","title":"播放和打印演示文稿"},{"id":"5.6","title":"演示文稿的其他功能"}]},{"number":6,"title":"计算机网络及网页制作","summary":"网络结构、Internet应用、HTML、网页与信息检索。","sections":[{"id":"6.1","title":"计算机网络概述"},{"id":"6.2","title":"计算机网络系统"},{"id":"6.3","title":"Internet 基础和应用"},{"id":"6.4","title":"网页、网页制作及 HTML 简介"},{"id":"6.5","title":"信息检索"}]},{"number":7,"title":"数字多媒体技术基础","summary":"多媒体特征、媒体元素、图像格式、颜色和视频。","sections":[{"id":"7.1","title":"数字多媒体技术概述"},{"id":"7.2","title":"数字多媒体系统组成及常用软件"},{"id":"7.3","title":"常用多媒体制作软件"}]},{"number":8,"title":"信息安全","summary":"安全属性、恶意软件、防火墙、密码技术和信息伦理。","sections":[{"id":"8.1","title":"信息安全概述"},{"id":"8.2","title":"计算机病毒"},{"id":"8.3","title":"防火墙"},{"id":"8.4","title":"Windows 10 操作系统安全"},{"id":"8.5","title":"信息伦理"}]},{"number":9,"title":"信息技术前沿","summary":"虚拟现实、云计算、物联网、区块链与人工智能。","sections":[{"id":"9.1","title":"虚拟现实和增强现实"},{"id":"9.2","title":"云计算和高性能计算"},{"id":"9.3","title":"物联网技术"},{"id":"9.4","title":"大数据技术"},{"id":"9.5","title":"区块链技术"},{"id":"9.6","title":"人工智能"},{"id":"9.7","title":"量子信息"},{"id":"9.8","title":"元宇宙"}]},{"number":10,"title":"数据库技术基础","summary":"关系数据库、数据库管理系统、关系运算、SQL与NoSQL。","sections":[{"id":"10.1","title":"数据库技术基础"},{"id":"10.2","title":"数据库管理系统"},{"id":"10.3","title":"数据库设计与 NoSQL"}]},{"number":11,"title":"计算思维","summary":"计算思维、算法表示、算法特征和基本控制结构。","sections":[{"id":"11.1","title":"计算思维"},{"id":"11.2","title":"计算思维与算法"},{"id":"11.3","title":"算法的控制结构"},{"id":"11.4","title":"面向对象程序设计"},{"id":"11.5","title":"基础算法设计思想"}]}],"notes":[{"q":3,"chapter":11,"section":"11.1","type":"单选","topic":"计算思维","title":"计算思维不是计算机科学家的专属思维","trigger":"真题直接考查计算思维的适用范围和常见方法。","conclusion":"计算思维是一套可用于多学科问题求解的思维方法，并非计算机科学家专属。","points":["常见过程包括分解、抽象、模式识别和算法设计。","它可以借助计算机，也可以先在纸面上形成问题模型。","医学、管理、工程和日常决策都可使用计算思维。","抽象保留与目标相关的要素、忽略暂时无关细节；自动化把明确的过程交给机器执行。计算思维是人的问题求解方式，不只是机械操作计算机。","教学示例：统计班级不及格人数。先确定输入是有效成绩列表，输出是不及格人数；规则为成绩小于60，不必保留与计数无关的姓名和座位号。","分解过程：核验输入→计数器C置0→逐个读成绩→若成绩\u003c60则C加1→读完输出C。这把现实任务转为可由人或机器执行的步骤。","用59、60、80检验应输出1；再检查空列表输出0、全部不及格是否等于列表长度。缺考或非法成绩如何处理应先写进输入规则，而不是让程序自行猜测。"],"boundary":"计算思维不等于会操作软件，也不等于任何问题都必须写程序。","id":"y2025q4","sources":[{"year":2023,"q":3,"type":"单选"},{"year":2025,"q":4,"type":"单选"},{"year":2021,"q":23,"type":"多选","page":4}],"keys":["2023-3","2025-4","2021-23"],"related":[{"id":"y2026q42","label":"伪代码用接近自然语言的结构描述算法","reason":"把分解和抽象所得的求解过程写成伪代码，可在选择具体编程语言之前讨论算法。"},{"id":"y2025q24","label":"面向对象用类、对象、封装和消息组织程序","reason":"类把共同属性与行为抽象出来，是计算思维中保留关键要素的一种程序组织实例。"}],"pointGroups":[{"title":"已有知识","indices":[0,1,2,3]},{"title":"把现实问题写成明确输入、规则和输出","indices":[4,5,6]}]},{"q":42,"chapter":11,"section":"11.1","type":"填空","topic":"算法表示","title":"伪代码用接近自然语言的结构描述算法","trigger":"题目要求填写一种不依赖具体编程语言的算法表示方法。","conclusion":"伪代码用结构化、近似程序的文字表达算法逻辑，不要求遵守某门语言的完整语法。","points":["伪代码应清楚体现输入、处理、输出和控制结构。","它便于编码前讨论逻辑。例如求3、8、5的最大值：m先取3，看到8更大就改为8，再与5比较后保持8，最后输出8。若只写“选一个合适的数”，因为“合适”未定义，无法据此执行。","流程图也可表示算法，但形式是图形符号和流程线。","自然语言、伪代码、流程图可描述算法步骤；E-R图描述实体及联系，不是算法流程图。"],"boundary":"伪代码没有唯一语法，却仍应保持关键词、缩进和变量含义一致。","id":"y2026q42","sources":[{"year":2026,"q":42,"type":"填空"},{"year":2022,"q":5,"type":"单选"}],"keys":["2026-42","2022-5"],"related":[{"id":"y2026q6","label":"算法必须确定、可行、有限并产生输出","reason":"伪代码没有统一语法，但描述的算法仍需明确、可行、有输出并能终止。"},{"id":"y2026q5","label":"顺序、分支和循环可以相互嵌套","reason":"顺序、分支与循环是伪代码中表达控制逻辑的基本结构，缩进应清楚体现嵌套关系。"},{"id":"y2025q11","label":"数据库设计不因规模小而省略","reason":"流程图描述算法步骤，E-R图描述实体及联系；看见图形表达不能把两者归为同一种设计。"}],"pointGroups":null},{"q":3,"target":null,"page":1,"chapter":11,"section":"11.2","topic":"队列","title":"队列先进先出，多队列交错不能打乱各自顺序","conclusion":"队列从队尾加入、从队头取出，遵循FIFO；多个队列可以交替出队，但各自内部先后顺序保持不变。","points":["车道一按A、B、C、D排队，车道二按E、F、G、H排队，每次只能放行某车道队首。","ABEFCDGH是合法交错；AFEBCDGH中F先于E，违反第二队列顺序。","判断一串输出是否合法，可分别抽出属于每个队列的元素，检查相对次序是否保持。","栈是后进先出LIFO，操作限制与队列不同。"],"boundary":"队列先后只约束本队列；不能据此断言A必定先于另一队列的E。","type":"单选","trigger":"围绕队列的识别、应用与易错边界整理。","id":"y2021q3","sources":[{"year":2021,"q":3,"type":"单选"}],"keys":["2021-3"],"related":[{"id":"y2026q7","label":"并发、共享、虚拟和异步描述不同操作系统现象","reason":"多队列交替出队可帮助理解任务交错推进；调度次序变化不代表各自应守的操作规则消失。"}]},{"q":33,"target":null,"chapter":11,"section":"11.2","topic":"算法复杂度","title":"时间复杂度与空间复杂度不必同向变化","conclusion":"时间复杂度描述运算量随输入规模增长的趋势；空间复杂度描述所需存储空间的增长趋势，两者没有必然正比例关系。","points":["同一问题可用缓存结果换取更少重复计算，这是以空间换时间。","逐个扫描n项求和，主要加法次数随n成比例增长，通常为O(n)时间；只保留当前累计值，需要O(1)额外空间。O(1)表示额外空间不随n增长，不是完全不占空间。","前缀和把“到当前位置为止的和”预先存好。例如数据3、5、2对应前缀和0、3、8、10，第2至3项的和可算10−3=7，不用再逐项相加。建表需O(n)时间和空间，之后每次区间求和为O(1)。","枚举检查候选解，递推从已知小规模结果推进，分治把问题分成较小子问题再合并结果；是否适用取决于问题结构。二分查找要依赖有序数据，不能对任意无序表直接使用。","分析循环时看实际执行次数：从1到n每次加1通常是线性次数；每次把规模减半通常是对数次数。嵌套循环不能只数层数，还要检查各层边界及依赖关系。"],"boundary":"复杂度描述规模增长趋势，不是一次运行秒数或某台电脑的内存容量；应说明是否统计额外空间。前缀和适合数据不变且有多次查询的情形，数据修改后原缓存可能需要更新。","type":"判断","trigger":"从算法复杂度的判断与应用整理。","id":"y2022q33","sources":[{"year":2022,"q":33,"type":"判断"}],"keys":["2022-33"],"related":[{"id":"y2024q69","label":"一趟升序冒泡把最大值推到右端","reason":"冒泡排序通常用O(n²)时间和O(1)额外空间，是时间与空间增长不必同向的具体例子。"},{"id":"y2022q43","label":"先初始化，再累加，再推进循环变量","reason":"将1至10累加推广到n项，逐项扫描需O(n)时间而累计变量只需O(1)额外空间。"},{"id":"y2026q45","label":"算力表示计算设备处理数据的能力","reason":"复杂度描述随输入规模的增长，算力描述设备处理能力，不能用一次运行秒数代替复杂度。"}],"pointGroups":[{"title":"核心知识","indices":[0,1,2]},{"title":"算法优化先数主要操作，再看额外空间","indices":[3,4]}]},{"q":4,"chapter":11,"section":"11.2","type":"单选","topic":"算法特征与评价","title":"算法必须确定、可行、有限并产生输出","trigger":"真题从输出、可行性和实现前评价考查算法的基本特征。","conclusion":"算法可以没有外部输入，但至少有一个输出；每一步应确定、可行，并在有限步骤后结束，也可以在编码前分析正确性与复杂度。","points":["确定性要求每一步含义明确，可行性要求操作能在有限资源下执行。","时间复杂度和空间复杂度可依据算法结构分析。","程序是算法的一种实现，测试实现不能代替算法论证。","算法允许零个或多个输入，但必须有一个或多个输出；“输入必须有、输出可以无”把条件写反。","辗转相除法每轮用“当前除数、非零余数”作为下一轮输入。例如48÷18余12，18÷12余6，12÷6余0，输出当前除数6。非零余数逐轮严格变小且不能无限下降，因此会终止；首轮整除时直接输出该轮除数。"],"boundary":"伪代码仍需转成可执行程序；“程序跑起来”也不等于算法正确或高效。","id":"y2026q6","sources":[{"year":2024,"q":4,"type":"单选"},{"year":2025,"q":5,"type":"单选"},{"year":2026,"q":6,"type":"单选"},{"year":2022,"q":6,"type":"单选"}],"keys":["2024-4","2025-5","2026-6","2022-6"],"related":[{"id":"y2026q42","label":"伪代码用接近自然语言的结构描述算法","reason":"可先用伪代码表达算法，再检查每一步含义、输入域、输出和终止条件是否清楚。"},{"id":"y2022q33","label":"时间复杂度与空间复杂度不必同向变化","reason":"算法在编码前即可分析时间和空间复杂度，运行测试与增长趋势分析回答不同问题。"},{"id":"y2021q33","label":"流程图要按箭头追踪，判断位置决定是否先执行一轮","reason":"循环的初值、变量推进和判断位置共同决定结果及能否终止，可用实际追踪检验算法条件。"}],"pointGroups":[{"title":"明确步骤、输入输出与终止条件","indices":[0,3,4]},{"title":"分析复杂度并区分算法与实现","indices":[1,2]}],"workedExamples":[{"year":2024,"q":4,"questionSummary":"判断算法是否必须编程后才能评价。","reasoning":["算法是问题求解的明确步骤，程序是算法的一种实现。","即使尚未编码，也能检查步骤是否正确、是否终止，并估算主要操作次数与额外空间。","因此“必须实现后才能评价”的绝对前提不成立；具体运行时间还会受语言实现和机器环境影响。"],"pitfall":"把抽象算法的分析等同于程序跑出来的秒数。","transfer":"拿两个寻找最大值的方法先数比较次数，再谈实现语言；能分析复杂度不等于已经知道实测耗时。","sourceURL":"https://www.aipta.com/article/10360.html","sourceStatus":"公开转录题面已读，原卷扫描待核","historicalVersionNote":""}]},{"q":33,"target":null,"page":5,"chapter":11,"section":"11.3","topic":"先执行后判断","title":"流程图要按箭头追踪，判断位置决定是否先执行一轮","conclusion":"本例先执行S=S+k，再令k=k+3，最后判断k＜10；从S=0、k=1开始，累加1、4、7后输出12。判断位置、条件方向和变量更新顺序要一起追踪。","points":["每轮记录执行前的k、累加后的S、更新后的k以及继续条件真假，按流程箭头实际经过的顺序执行。","第一轮S=1、k=4；第二轮S=5、k=7；第三轮S=12、k=10，条件不成立退出，因此10未被累加。","把继续条件改成k≤10，会再累加10，随后k变为13，输出变为22；边界等号是否存在会改变执行次数。","后测试循环先执行循环体，至少执行一次；先测试循环先判断，初始条件不成立时可能执行0次。","例如仍取S=0、k=1，但边界设为1：本例后测试写法会先加1再退出；将条件移到循环体之前则一次也不加。","S应在循环外初始化；循环变量必须按规则推进，使退出条件最终能满足。赋值S=S+k是用旧值计算后写回，不是代数恒等式。"],"boundary":"判断框移到循环体前后、把＜改成≤、或把k的更新提前，都可能改变结果；箭头上的“是/否”通向哪里也必须与条件一起阅读。","type":"填空","trigger":"围绕先执行后判断的识别、应用与易错边界整理。","id":"y2021q33","sources":[{"year":2021,"q":33,"type":"填空"}],"keys":["2021-33"],"comparison":{"headers":["条件与结构","累加项","输出"],"rows":[["本例后测试，k＜10","1、4、7","12"],["本例后测试，k≤10","1、4、7、10","22"],["边界1，后测试","1","1"],["边界1，先测试","无","0"]]},"related":[{"id":"y2022q43","label":"先初始化，再累加，再推进循环变量","reason":"对照先判断的累加循环，观察同样的初始化和更新操作如何因判断位置不同改变执行次数。"},{"id":"y2026q5","label":"顺序、分支和循环可以相互嵌套","reason":"先辨认顺序执行、条件判断和循环回边，再按流程箭头追踪每一轮。"},{"id":"y2026q6","label":"算法必须确定、可行、有限并产生输出","reason":"循环变量推进和退出条件是算法有限性的具体要求，初始条件与边界情况也需覆盖。"}],"pointGroups":[{"title":"初始化并按真实执行顺序追踪状态","indices":[0,1,5]},{"title":"改变边界或判断位置后再比较","indices":[2,3,4]}]},{"q":43,"target":null,"chapter":11,"section":"11.3","topic":"累加循环","title":"先初始化，再累加，再推进循环变量","conclusion":"S=0、i=1；当i≤10时执行S=S+i、i=i+1，最终S为55。","points":["S保存累计结果，i保存当前加数。从(S,i)=(0,1)开始，前三轮执行后依次为(1,2)、(3,3)、(6,4)：每轮先把当前i加进S，再推进i。","S应在循环外初始化。若每轮相加前都重新令S=0，前面的和就被覆盖；本例最终只会留下最后一次的加数10。","最后一次相加使用i=10，之后i变成11，条件不成立才退出。","可用等差数列1+…+10=10×11÷2核验，不替代逐步理解循环。"],"boundary":"S=S+i是赋值更新，不是代数恒等式；把推进语句提前会改变被累加的数列。","type":"填空","trigger":"从累加循环的判断与应用整理。","id":"y2022q43","sources":[{"year":2022,"q":43,"type":"填空"}],"keys":["2022-43"],"related":[{"id":"y2021q33","label":"流程图要按箭头追踪，判断位置决定是否先执行一轮","reason":"将判断框移到循环体后，或改变更新顺序与边界等号，会改变参与累加的项。"},{"id":"y2023q69","label":"计数循环要同时检查初值、边界、条件和累加器","reason":"求和累加器加当前数值，人数计数器只在条件成立时加1；两者都应在循环外初始化。"},{"id":"y2022q33","label":"时间复杂度与空间复杂度不必同向变化","reason":"逐项累加可推广为O(n)时间、O(1)额外空间，前缀和则展示为多次查询增加存储的取舍。"}],"pointGroups":null},{"q":69,"chapter":11,"section":"11.3","type":"分析","topic":"循环计数","title":"计数循环要同时检查初值、边界、条件和累加器","trigger":"两道连续分析题补全处理45名学生的循环条件，并解释不及格人数累加语句。","conclusion":"先用i保证每人成绩恰好处理一次，再用C只统计不及格者。若从i=1开始，每轮处理一人后加1，45人用i≤45；C在循环前置0，成绩＜60时才执行C=C+1。","points":["初值和边界必须配套：i从1到45，含两端，共45次；i从0到44，同样45次，可写i＜45。若把i=1与i＜45搭配，只处理44人；把i=0与i≤45搭配则处理46次。","C=C+1是赋值：先读出旧C，加1，再写回C；不是解方程。i记录处理进度，C记录满足条件的人数，即使某人成绩及格，i也仍要推进。","只有成绩＜60时才增加C；恰好60分不满足这一条件。循环总次数等于处理人数，分支执行次数才是不及格人数。","用三个人缩小推演：成绩依次59、60、58，C从0开始；读59后C=1，读60后仍为1，读58后C=2。共执行3轮，但只执行2次C=C+1，最终输出2。","C必须在循环前初始化一次。若每轮都把C置0，本例最终得到1，只反映最后一人成绩；若漏掉初始化，累计值没有可靠起点。"],"boundary":"这里按“先判断是否还有人→读取本人成绩→按条件计数→推进i”推演；改变读入位置或更新顺序后应重新走一遍。初值、最后一次处理的序号、退出时的i与最终C是四个不同问题。","id":"y2023q69","sources":[{"year":2023,"q":69,"type":"分析"},{"year":2023,"q":70,"type":"分析"}],"keys":["2023-69","2023-70"],"related":[{"id":"y2022q43","label":"先初始化，再累加，再推进循环变量","reason":"比较S=S+i与C=C+1，区分累计数值和累计满足条件的记录数，并检查初始化位置。"},{"id":"y2026q5","label":"顺序、分支和循环可以相互嵌套","reason":"不及格计数是在循环内嵌套分支，只有分支条件成立才更新计数器。"},{"id":"y2021q51","label":"COUNTIF、COUNTIFS与AVERAGEIF：条件计数和条件平均","reason":"COUNTIF把逐行判断后计数封装为表格函数，多条件计数仍要求同一记录满足相应条件。"}],"pointGroups":[{"title":"初值、边界与每轮执行顺序","indices":[0,1]},{"title":"不及格条件与三值计数轨迹","indices":[2,3]},{"title":"初始化位置为何改变结果","indices":[4]}]},{"q":25,"chapter":11,"section":"11.3","type":"多选","topic":"控制结构","title":"顺序、分支和循环可以相互嵌套","trigger":"两道题综合判断三种基本控制结构的含义和嵌套关系。","conclusion":"顺序按先后执行，分支按条件选择路径，循环在终止条件控制下重复；三者可以结构化嵌套。","points":["分支可表达条件成立执行A，否则执行B。","循环由循环体和循环控制条件构成。","结构化组合有助于保持流程可追踪。"],"boundary":"“外层是顺序结构”不意味着内部不能含分支或循环。","id":"y2026q5","sources":[{"year":2025,"q":25,"type":"多选"},{"year":2026,"q":5,"type":"单选"}],"keys":["2025-25","2026-5"],"related":[{"id":"y2026q42","label":"伪代码用接近自然语言的结构描述算法","reason":"伪代码用关键词和缩进表达顺序、分支、循环及其嵌套，便于在编码前检查逻辑。"},{"id":"y2023q69","label":"计数循环要同时检查初值、边界、条件和累加器","reason":"处理多名学生并只统计不及格者，是循环中嵌套分支的完整实例。"},{"id":"y2024q69","label":"一趟升序冒泡把最大值推到右端","reason":"冒泡排序在重复扫描中进行相邻比较并按条件交换，可练习追踪循环与分支的组合。"}]},{"q":24,"chapter":11,"section":"11.4","type":"多选","topic":"面向对象","title":"面向对象用类、对象、封装和消息组织程序","trigger":"题目要求识别面向对象程序设计的基本思想与方法。","conclusion":"面向对象以类和对象为核心，通过封装组织数据与操作，并通过消息或方法调用建立对象协作。","points":["类描述一类对象共同的属性和行为。例如“学生”类可规定学号、姓名、成绩等属性，以及修改成绩等方法。","对象是类的具体实例。“学号01的王宁”和“学号02的李明”可来自同一学生类，但各自保存自己的成绩状态。","封装把数据与操作组织在一起，并控制外部访问。例如通过“修改成绩”方法检查0—100的范围，再更新对象内部成绩；调用者按公开接口使用，不必直接改内部存储。","继承复用或扩展已有类型；多态使相同接口可由不同对象给出各自实现。例如同样调用“计算面积”，圆对象按圆的规则计算，矩形对象按长×宽计算。消息或方法调用用来请求对象完成操作。"],"boundary":"面向对象不是结构化程序设计的同义词；二者可以在同一系统中结合使用。","id":"y2025q24","sources":[{"year":2025,"q":24,"type":"多选"},{"year":2022,"q":23,"type":"多选"}],"keys":["2025-24","2022-23"],"related":[{"id":"y2025q4","label":"计算思维不是计算机科学家的专属思维","reason":"类抽取共同属性和行为，可与计算思维的抽象联系起来；对象则是这个抽象的具体实例。"},{"id":"y2026q5","label":"顺序、分支和循环可以相互嵌套","reason":"面向对象负责组织数据和操作，方法内部仍能使用顺序、分支和循环，二者可在同一程序中结合。"}],"pointGroups":null},{"q":69,"chapter":11,"section":"11.5","type":"分析","topic":"冒泡排序","title":"一趟升序冒泡把最大值推到右端","trigger":"两道连续分析题先补比较条件，再追踪一趟排序结果。","conclusion":"本例从左向右进行升序冒泡：仅在a[j]＞a[j+1]时交换相邻元素，一趟后本趟最大值到右端；8、5、2、9、7、3的一趟结果是5、2、8、7、3、9。","points":["每一步先比较当前相邻元素，再决定是否交换；不能不看数值就按固定脚本交换。","第一次完整从左向右扫描n个元素需比较n−1对；完成一趟通常只保证一个最大值就位，不代表整个序列有序。","后续趟可缩短尚未排序的范围；有提前结束标记的版本在某一整趟没有交换时即可结束。","保持扫描方向不变，把交换条件改为左值小于右值可得到降序；若从右向左扫描，升序一趟通常是把最小值移到左端，因此要先看循环方向。","相等元素不交换，可保持它们原有的相对次序；判断稳定性应给重复值附上身份，如3甲与3乙。","一般冒泡排序的平均及最坏时间复杂度为O(n²)，额外空间为O(1)；有提前结束判断时，已经有序的输入只需一趟扫描。"],"boundary":"“一趟冒泡”的结果取决于扫描方向和比较条件，不能只背最大值到右端；一趟结束与全表有序是两个状态。","id":"y2024q69","sources":[{"year":2024,"q":69,"type":"分析"},{"year":2024,"q":70,"type":"分析"}],"keys":["2024-69","2024-70"],"comparison":{"headers":["本例操作","保证什么","不保证什么"],"rows":[["一次相邻比较","纠正这一对的逆序关系","整个序列已排序"],["一趟从左到右升序扫描","未排序范围最大值到右端","其余元素全部有序"],["整趟没有交换","当前范围已经有序","所有实现都自动提前结束"]]},"related":[{"id":"y2022q33","label":"时间复杂度与空间复杂度不必同向变化","reason":"比较冒泡的O(n²)时间、O(1)额外空间，以及提前结束版本的有序输入情况，理解复杂度评价的条件。"},{"id":"y2026q5","label":"顺序、分支和循环可以相互嵌套","reason":"先识别扫描循环，再在每次相邻比较后判断是否交换，避免把一趟排序误读成固定交换脚本。"}],"pointGroups":[{"title":"按扫描方向与交换条件追踪一趟","indices":[0,1,3]},{"title":"整表结束、稳定性与复杂度","indices":[2,4,5]}]}],"sourceCount":460,"years":[2020,2021,2022,2023,2024,2025,2026]};
